            if len(rdata) != 4:
                raise RecordError("A rdata must be 4 bytes")
            try:
                address = str(ipaddress.IPv4Address(rdata))
            except ValueError:
                raise RecordError("invalid A rdata") from None
            lines.append(prefix + "A " + address)
